  1→import { computed } from "@angular/core";
  2→import {
  3→  patchState,
  4→  signalStore,
  5→  withComputed,
  6→  withMethods,
  7→  withState,
  8→} from "@ngrx/signals";
  9→import type {
 10→  EventSnapshot,
 11→  IssueSnapshot,
 12→  ScoreSnapshot,
 13→  SnapshotWithScore,
 14→  TimeSnapshot,
 15→} from "./engine-api.service";
 16→import type { ActiveDecision, ScenarioContext } from "./decision-api.service";
 17→import type { ScoreChange, SystemSnapshot, SystemStateChange } from "./generated/state-changes.types";
 18→import { formatTimeMs } from "./format-time";
 19→
 20→export interface ParticipantPresence {
 21→  id: string;
 22→  display_name: string;
 23→  role: string | null;
 24→  connected: boolean;
 25→}
 26→
 27→interface ScoreState {
 28→  totalScore: number;
 29→  turnNumber: number;
 30→  nextDecisionTimeMs: number;
 31→  stress: number;
 32→}
 33→
 34→interface ExerciseState {
 35→  exerciseId: number | null;
 36→  title: string;
 37→  phase: string;
 38→  gameMode: string;
 39→  practiceMode: boolean;
 40→  playTimeMs: number;
 41→  realTimeMs: number;
 42→  speedFactor: number;
 43→  paused: boolean;
 44→  events: EventSnapshot[]; // domain: "injects"
 45→  issues: IssueSnapshot[]; // domain: "defects"
 46→  decisions: ActiveDecision[];
 47→  systems: SystemSnapshot[];
 48→  participants: ParticipantPresence[];
 49→  context: ScenarioContext | null;
 50→  participantId: string;
 51→  playerRole: string;
 52→  playerType: string;
 53→  score: ScoreState | null;
 54→  loading: boolean;
 55→  error: string | null;
 56→}
 57→
 58→const initialState: ExerciseState = {
 59→  exerciseId: null,
 60→  title: "",
 61→  phase: "setup",
 62→  gameMode: "classic",
 63→  practiceMode: false,
 64→  playTimeMs: 0,
 65→  realTimeMs: 0,
 66→  speedFactor: 1,
 67→  paused: true,
 68→  events: [],
 69→  issues: [],
 70→  decisions: [],
 71→  systems: [],
 72→  participants: [],
 73→  context: null,
 74→  participantId: "",
 75→  playerRole: "player",
 76→  playerType: "advisor",
 77→  score: null,
 78→  loading: false,
 79→  error: null,
 80→};
 81→
 82→export const ExerciseStore = signalStore(
 83→  withState(initialState),
 84→
 85→  withComputed((store) => ({
 86→    rtClock: computed(() => formatTimeMs(store.realTimeMs())),
 87→    ptClock: computed(() => formatTimeMs(store.playTimeMs())),
 88→    activeEvents: computed(() =>
 89→      store.events().filter((e) => e.lifecycle === "running"),
 90→    ), // active injects
 91→    scheduledEvents: computed(() =>
 92→      store.events().filter((e) => e.lifecycle === "scheduled"),
 93→    ), // scheduled injects
 94→    completedEvents: computed(() =>
 95→      store.events().filter((e) => e.lifecycle === "completed"),
 96→    ), // completed injects
 97→    activeIssues: computed(() =>
 98→      store.issues().filter((i) => i.lifecycle === "active"),
 99→    ), // active defects
100→    /** Remaining ms on the active decision timer (null if no open decision with timeout). */
101→    decisionCountdownMs: computed(() => {
102→      const decision = store
103→        .decisions()
104→        .find((d) => d.status === "open" && d.timeout_ms > 0);
105→      if (!decision) return null;
106→      const factor = store.speedFactor() || 1;
107→      const openedAtRt = decision.opened_at_pt_ms / factor;
108→      const elapsed = store.realTimeMs() - openedAtRt;
109→      return Math.max(0, decision.timeout_ms - elapsed);
110→    }),
111→    /** Countdown clock: time remaining until the next scheduled event fires. */
112→    turnCountdownClock: computed(() => {
113→      const pt = store.playTimeMs();
114→      const nextEvent = store
115→        .events()
116→        .filter((e) => e.lifecycle === "scheduled" && e.scheduled_pt_ms > pt)
117→        .sort((a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms)[0];
118→      if (!nextEvent) return null;
119→      const remaining = Math.max(0, nextEvent.scheduled_pt_ms - pt);
120→      return formatTimeMs(remaining);
121→    }),
122→    issuesWithCountdown: computed(() => {
123→      const pt = store.playTimeMs();
124→      return store
125→        .issues()
126→        .filter(
127→          (i) =>
128→            i.lifecycle === "active" &&
129→            i.auto_resolve_ms > 0 &&
130→            i.activated_at_pt_ms !== null,
131→        )
132→        .map((i) => {
133→          const elapsed = pt - (i.activated_at_pt_ms ?? 0);
134→          const remaining = Math.max(0, i.auto_resolve_ms - elapsed);
135→          return { ...i, remaining_ms: remaining };
136→        });
137→    }),
138→    releasedIssues: computed(() => store.issues().filter((i) => i.released)),
139→    openDecisions: computed(() =>
140→      store.decisions().filter((d) => d.status === "open"),
141→    ),
142→    hasOpenDecision: computed(
143→      () => store.decisions().filter((d) => d.status === "open").length > 0,
144→    ),
145→    connectedParticipants: computed(() =>
146→      store.participants().filter((p) => p.connected),
147→    ),
148→    connectedCount: computed(
149→      () => store.participants().filter((p) => p.connected).length,
150→    ),
151→    isCollaborative: computed(
152→      () => store.gameMode() === "simple_collaborative",
153→    ),
154→    isDecisionMaker: computed(() => store.playerType() === "decision_maker"),
155→    isAllAdvisors: computed(() => store.playerRole() === "all_advisors"),
156→    isPracticeMode: computed(() => store.practiceMode()),
157→    phaseBadgeVariant: computed<"default" | "secondary" | "destructive">(() => {
158→      switch (store.phase()) {
159→        case "running":
160→          return "default";
161→        case "paused":
162→          return "secondary";
163→        case "completed":
164→          return "destructive";
165→        default:
166→          return "secondary";
167→      }
168→    }),
169→  })),
170→
171→  withMethods((store) => ({
172→    setExerciseId(id: number): void {
173→      patchState(store, { exerciseId: id });
174→    },
175→
176→    applySnapshot(snapshot: SnapshotWithScore): void {
177→      patchState(store, {
178→        exerciseId: snapshot.exercise_id,
179→        title: snapshot.title,
180→        phase: snapshot.phase,
181→        playTimeMs: snapshot.time.play_time_ms,
182→        realTimeMs: snapshot.time.real_time_ms,
183→        speedFactor: snapshot.time.factor,
184→        paused: snapshot.time.paused,
185→        events: snapshot.events,
186→        issues: snapshot.issues,
187→        systems: snapshot.systems ?? store.systems(),
188→        decisions: snapshot.decisions ?? store.decisions(),
189→        score: snapshot.score
190→          ? {
191→              totalScore: snapshot.score.total_score,
192→              stress: snapshot.score.stress,
193→              turnNumber: snapshot.score.turn_number,
194→              nextDecisionTimeMs: snapshot.score.next_decision_time_ms,
195→            }
196→          : store.score(),
197→        loading: false,
198→        error: null,
199→      });
200→    },
201→
202→    applyTimeUpdate(time: TimeSnapshot): void {
203→      patchState(store, {
204→        playTimeMs: time.play_time_ms,
205→        realTimeMs: time.real_time_ms,
206→        speedFactor: time.factor,
207→        paused: time.paused,
208→      });
209→    },
210→
211→    /** Advance clocks locally by wall-clock delta (call from a setInterval). */
212→    tick(wallDeltaMs: number): void {
213→      if (store.paused()) return;
214→      const factor = store.speedFactor();
215→      patchState(store, {
216→        realTimeMs: store.realTimeMs() + wallDeltaMs,
217→        playTimeMs: store.playTimeMs() + wallDeltaMs * factor,
218→      });
219→    },
220→
221→    applyPhaseChange(phase: string): void {
222→      patchState(store, { phase });
223→    },
224→
225→    updateEvent(eventId: string, lifecycle: string): void {
226→      const events = store
227→        .events()
228→        .map((e) => (e.id === eventId ? { ...e, lifecycle } : e));
229→      patchState(store, { events });
230→    },
231→
232→    updateIssue(issueId: string, lifecycle: string, released?: boolean): void {
233→      const issues = store
234→        .issues()
235→        .map((i) =>
236→          i.id === issueId
237→            ? { ...i, lifecycle, released: released ?? i.released }
238→            : i,
239→        );
240→      patchState(store, { issues });
241→    },
242→
243→    setLoading(loading: boolean): void {
244→      patchState(store, { loading });
245→    },
246→
247→    setError(error: string): void {
248→      patchState(store, { error, loading: false });
249→    },
250→
251→    applyDecisions(decisions: ActiveDecision[]): void {
252→      patchState(store, { decisions });
253→    },
254→
255→    setContext(ctx: ScenarioContext): void {
256→      patchState(store, { context: ctx });
257→    },
258→
259→    setParticipantId(id: string): void {
260→      patchState(store, { participantId: id });
261→    },
262→
263→    setPlayerRole(role: string): void {
264→      patchState(store, { playerRole: role });
265→    },
266→
267→    closeDecision(decisionId: string): void {
268→      const decisions = store
269→        .decisions()
270→        .map((d) => (d.id === decisionId ? { ...d, status: "closed" } : d));
271→      patchState(store, { decisions });
272→    },
273→
274→    updatePresence(participants: ParticipantPresence[]): void {
275→      patchState(store, { participants });
276→    },
277→
278→    setGameMode(mode: string): void {
279→      patchState(store, { gameMode: mode });
280→    },
281→
282→    setPracticeMode(practice: boolean): void {
283→      patchState(store, { practiceMode: practice });
284→    },
285→
286→    setPlayerType(playerType: string): void {
287→      patchState(store, { playerType });
288→    },
289→
290→    setSpeedFactor(factor: number): void {
291→      patchState(store, { speedFactor: factor });
292→    },
293→
294→    applyScoreChange(change: Pick<ScoreChange, "total_score" | "stress" | "next_decision_time_ms" | "turn_number">): void {
295→      patchState(store, {
296→        score: {
297→          totalScore: change.total_score,
298→          stress: change.stress,
299→          nextDecisionTimeMs: change.next_decision_time_ms,
300→          turnNumber: change.turn_number,
301→        },
302→      });
303→    },
304→
305→    applyRecommendation(
306→      decisionId: string,
307→      participantId: string,
308→      optionId: string,
309→    ): void {
