import { computed } from "@angular/core";
import {
  patchState,
  signalStore,
  withComputed,
  withMethods,
  withState,
} from "@ngrx/signals";
import type {
  EventSnapshot,
  IssueSnapshot,
  ScoreSnapshot,
  SnapshotWithScore,
  TimeSnapshot,
} from "./engine-api.service";
import type { ActiveDecision, ScenarioContext } from "./decision-api.service";
import type { ScoreChange, SystemSnapshot, SystemStateChange } from "./generated/state-changes.types";
import { formatTimeMs } from "./format-time";

export interface ParticipantPresence {
  id: string;
  display_name: string;
  role: string | null;
  connected: boolean;
}

interface ScoreState {
  totalScore: number;
  turnNumber: number;
  nextDecisionTimeMs: number;
  stress: number;
}

interface ExerciseState {
  exerciseId: number | null;
  title: string;
  phase: string;
  gameMode: string;
  practiceMode: boolean;
  playTimeMs: number;
  realTimeMs: number;
  speedFactor: number;
  paused: boolean;
  events: EventSnapshot[]; // domain: "injects"
  issues: IssueSnapshot[]; // domain: "defects"
  decisions: ActiveDecision[];
  systems: SystemSnapshot[];
  participants: ParticipantPresence[];
  context: ScenarioContext | null;
  participantId: string;
  playerRole: string;
  playerType: string;
  score: ScoreState | null;
  loading: boolean;
  error: string | null;
}

const initialState: ExerciseState = {
  exerciseId: null,
  title: "",
  phase: "setup",
  gameMode: "classic",
  practiceMode: false,
  playTimeMs: 0,
  realTimeMs: 0,
  speedFactor: 1,
  paused: true,
  events: [],
