() => {
  const ng = window.ng;
  const el = document.querySelector('tfc-player-view');
  const comp = ng.getComponent(el);
  const store = comp.store;
  return {
    turnNumber: store.score()?.turnNumber,
    stress: store.score()?.stress,
    openDecisions: store.openDecisions().map(d => ({ id: d.id, title: d.title })),
    runningEvents: store.events().filter(e => e.lifecycle === 'running').map(e => ({ id: e.id, title: e.title })),
    scheduledEvents: store.events().filter(e => e.lifecycle === 'scheduled').map(e => e.id),
  };
}

