async () => {
  // Helper to play one turn: for each card with a submit button,
  // select the first checkbox and click submit
  const results = [];

  async function playTurn() {
    // Find all submit buttons
    const submitBtns = [...document.querySelectorAll('button')].filter(b => b.textContent.trim() === 'Submit');
    if (submitBtns.length === 0) return false;

    for (const btn of submitBtns) {
      if (btn.disabled) {
        // Find the card container and check the first unchecked checkbox
        const card = btn.closest('.role-card, [class*="card"]') || btn.parentElement;
        const checkboxes = card ? card.querySelectorAll('input[type="checkbox"]') : [];
        for (const cb of checkboxes) {
          if (!cb.checked) {
            cb.click();
            await new Promise(r => setTimeout(r, 50));
            break;
          }
        }
      }
      // Wait a bit then click submit
      await new Promise(r => setTimeout(r, 100));
      if (!btn.disabled) {
        btn.click();
        await new Promise(r => setTimeout(r, 200));
      }
    }
    return true;
  }

  // Play current turn
  const played = await playTurn();

  // Get current state
  const ng = window.ng;
  const el = document.querySelector('tfc-player-view');
  const comp = ng.getComponent(el);
  const store = comp.store;

  return {
    played,
    turnNumber: store.score()?.turnNumber,
    stress: store.score()?.stress,
    openDecisions: store.openDecisions().length,
    phase: store.phase(),
  };
}

