293→    await page.locator("tfc-decision-panel").getByRole("button", { name: "Submit" }).click();
294→
295→    // Verify closure via API (decision panel stays because next decision chains instantly)
296→    await waitForDecisionClosed(exerciseId, "evt-t1");
297→  });
298→
299→  // ── Turns 2-15: multi-choice decision templates ────────────────
300→
301→  // After evt-t1 closes, the engine chains: on_decision_closed_v2 increments
302→  // current_index from 0→1, so get_next_decision_id returns decision_sequence[1] = dec-t2.
303→  // Each subsequent close chains to the next in sequence: dec-t3, dec-t4, ..., dec-t15.
304→
305→  for (let seqIdx = 1; seqIdx < DECISION_SEQUENCE.length; seqIdx++) {
306→    const decId = DECISION_SEQUENCE[seqIdx];
307→    const tpl = DECISION_TEMPLATES.find((t) => t.id === decId);
308→    if (!tpl) continue;
309→
310→    const turnLabel = `Turn ${seqIdx + 1}`;
311→
312→    test(`${turnLabel} — "${tpl.title}" renders and submits`, async ({
313→      page,
314→    }) => {
315→      // Wait for this specific decision to be open in the engine
316→      await waitForOpenDecision(exerciseId, decId, 15_000);
317→
318→      // Navigate to player view
319→      await page.goto(playerUrl());
320→      await dismissViteErrors(page);
321→
322→      // Wait for all-advisors panel with decision
323→      const advisorPanel = page.locator("tfc-all-advisors-panel");
324→      await expect(advisorPanel).toBeVisible({ timeout: 10_000 });
325→
326→      // Practice mode Phase 1: advisor dialog is open
327→      // Submit a recommendation using the top-scoring option
328→      const advisorCheckbox = advisorPanel.locator('input[type="checkbox"]').first();
329→      await expect(advisorCheckbox).toBeVisible({ timeout: 5_000 });
330→      const advisorPicks = topOptions(tpl);
331→      for (const pickId of advisorPicks.slice(0, 1)) {
332→        const opt = tpl.options.find((o) => o.id === pickId)!;
333→        await advisorPanel.getByText(opt.label).first().click();
334→      }
335→      await advisorPanel.getByRole("button", { name: "Submit" }).first().click();
336→
337→      // Click "Proceed to Decision" to move to Phase 2
338→      const proceedBtn = page.getByRole("button", {
339→        name: "Proceed to Decision",
340→      });
341→      await expect(proceedBtn).toBeVisible({ timeout: 5_000 });
342→      await proceedBtn.click();
343→
344→      // Phase 2: decision panel for the decision-maker
345→      const decisionPanel = page.locator("tfc-decision-panel");
346→      await expect(page.getByText(tpl.title)).toBeVisible({ timeout: 5_000 });
347→
348→      // Verify all options are rendered
349→      for (const opt of tpl.options) {
350→        await expect(page.getByText(opt.label)).toBeVisible();
351→      }
352→
353→      // Select top-scoring options (checkboxes)
354→      const picks = topOptions(tpl);
355→      for (const pickId of picks) {
356→        const opt = tpl.options.find((o) => o.id === pickId)!;
357→        await decisionPanel.getByText(opt.label).click();
358→      }
359→
360→      // Submit
361→      const submitBtn = decisionPanel.getByRole("button", { name: "Submit" });
362→      await expect(submitBtn).toBeEnabled();
363→      await submitBtn.click();
364→
365→      // Verify closure via API (decision panel stays because next decision chains instantly)
366→      await waitForDecisionClosed(exerciseId, decId);
367→    });
368→  }
369→
370→  // ── Post-game verification ─────────────────────────────────────
371→
372→  test("all 15 decisions completed — score reflects all turns", async () => {
373→    const snap = await getSnapshot(exerciseId);
374→
375→    const openDecs = snap.decisions.filter((d) => d.status === "open");
376→    expect(openDecs.length).toBe(0);
377→
378→    expect(snap.score).not.toBeNull();
379→    expect(snap.score?.turn_number).toBe(15);
380→    expect(snap.score?.total_score).toBeGreaterThan(0);
381→  });
382→
383→  test("final UI shows no decision overlay", async ({ page }) => {
384→    await page.goto(playerUrl());
385→    await dismissViteErrors(page);
386→
387→    // No active decision → no decision panel
388→    await expect(page.locator("tfc-decision-panel")).not.toBeVisible({ timeout: 5_000 });
389→    await expect(page.locator("tfc-all-advisors-panel")).not.toBeVisible({ timeout: 5_000 });
390→
391→    // Practice mode footer still visible
392→    await expect(
393→      page.getByText("Practice Mode — playing all roles"),
394→    ).toBeVisible();
395→
396→    // Score bar should show final turn
397→    await expect(page.locator("tfc-score-bar")).toBeVisible();
398→  });
399→});
