  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  computed,
  5→  effect,
  6→  input,
  7→  output,
  8→  signal,
  9→  untracked,
 10→} from "@angular/core";
 11→import { UpperCasePipe } from "@angular/common";
 12→import { BadgeComponent, ButtonDirective } from "@aspect/ui";
 13→import type { DecisionOption } from "../../core/decision-api.service";
 14→import { extractRecRoleId, type RoleCard } from "./role-card.types";
 15→
 16→export interface RoleCardSubmission {
 17→  roleId: string;
 18→  selectedOptions: string[];
 19→  freeText: string;
 20→}
 21→
 22→@Component({
 23→  selector: "tfc-role-card",
 24→  changeDetection: ChangeDetectionStrategy.OnPush,
 25→  imports: [UpperCasePipe, BadgeComponent, ButtonDirective],
 26→  template: `
 27→    <div class="role-card"
 28→      [class.role-card--intel]="card().status === 'intel'"
 29→      [class.role-card--active]="card().status === 'active'"
 30→      [class.role-card--done]="card().status === 'done'">
 31→
 32→      <!-- Header -->
 33→      <div class="role-card__header">
 34→        <span class="role-card__role-id">{{ card().roleId | uppercase }}</span>
 35→        <ui-badge [variant]="card().status === 'active' ? 'default' : 'secondary'">
 36→          {{ badgeLabel() }}
 37→        </ui-badge>
 38→      </div>
 39→      <div class="role-card__role-label">{{ card().roleLabel }}</div>
 40→
 41→      <!-- Intel -->
 42→      @if (card().intel) {
 43→        <div class="role-card__intel">{{ card().intel }}</div>
 44→      } @else if (card().decision) {
 45→        <div class="role-card__intel role-card__intel--empty">No role-specific intel this turn</div>
 46→      }
 47→
 48→      <!-- Advisor Recs (CO card only) -->
 49→      @if (card().advisorRecs.length > 0) {
 50→        <div class="role-card__recs">
 51→          <div class="role-card__recs-title">Advisor Recommendations</div>
 52→          @for (rec of card().advisorRecs; track rec.roleId) {
 53→            <div class="role-card__rec" [class.role-card__rec--pending]="!rec.selection">
 54→              <span class="role-card__rec-role">{{ rec.roleLabel }}:</span>
 55→              @if (rec.selection) {
 56→                <span class="role-card__rec-selection">{{ rec.selection }}</span>
 57→              } @else {
 58→                <span class="role-card__rec-pending">pending...</span>
 59→              }
 60→            </div>
 61→          }
 62→        </div>
 63→      }
 64→
 65→      <!-- Decision Form (active only) -->
 66→      @if (card().decision && card().status === 'active') {
 67→        <div class="role-card__decision">
 68→          @if (questionType() === 'single_choice' || questionType() === 'multi_choice') {
 69→            @for (option of filteredOptions(); track option.id) {
 70→              <label class="role-card__option" [class.role-card__option--selected]="isSelected(option.id)">
 71→                <input
 72→                  [type]="questionType() === 'single_choice' ? 'radio' : 'checkbox'"
 73→                  [name]="'role-decision-' + card().roleId"
 74→                  [checked]="isSelected(option.id)"
 75→                  (change)="toggleOption(option)"
 76→                />
 77→                <span>{{ option.label }}</span>
 78→              </label>
 79→            }
 80→          }
 81→          @if (questionType() === 'free_text') {
 82→            <textarea class="role-card__textarea"
 83→              [value]="freeText()"
 84→              (input)="onTextInput($event)"
 85→              placeholder="Enter your response..."></textarea>
 86→          }
 87→          <div class="role-card__actions">
 88→            <button uiButton variant="default" size="sm" (click)="onSubmit()" [disabled]="!canSubmit()">
 89→              Submit
 90→            </button>
 91→          </div>
 92→        </div>
 93→      }
 94→
 95→      <!-- Done State -->
 96→      @if (card().status === 'done') {
 97→        <div class="role-card__done">Selected: {{ doneLabel() }}</div>
 98→      }
 99→    </div>
100→  `,
101→})
102→export class RoleCardComponent {
103→  readonly card = input.required<RoleCard>();
104→  readonly submitted = output<RoleCardSubmission>();
105→
106→  readonly selectedOptions = signal<string[]>([]);
107→  readonly freeText = signal("");
108→
109→  private readonly resetOnCardChange = effect(() => {
110→    this.card();
111→    untracked(() => {
112→      this.selectedOptions.set([]);
113→      this.freeText.set("");
114→    });
115→  });
116→
117→  readonly filteredOptions = computed<DecisionOption[]>(() => {
118→    const decision = this.card().decision;
119→    if (!decision) return [];
120→    const playerType = this.card().playerType;
121→    const roleId = this.card().roleId;
122→    if (playerType === "decision_maker") {
123→      return decision.options;
124→    }
125→    // advisor: COMMON options (no role) + own-role options
126→    return decision.options.filter(
127→      (o) => !o.role || o.role === roleId,
128→    );
129→  });
130→
131→  readonly badgeLabel = computed<string>(() => {
132→    const status = this.card().status;
133→    if (status === "intel") return "INTEL";
134→    if (status === "active") return "DECISION";
135→    return "DONE";
136→  });
137→
138→  readonly questionType = computed<string>(() => {
139→    return this.card().decision?.question_type ?? "free_text";
140→  });
141→
142→  readonly doneLabel = computed<string>(() => {
143→    const decision = this.card().decision;
144→    if (!decision) return "";
145→    const roleId = this.card().roleId;
146→    const recEntry = Object.entries(decision.recommendations).find(
147→      ([key]) => extractRecRoleId(key) === roleId,
148→    );
149→    const optionId = recEntry?.[1];
150→    if (!optionId) return "";
151→    return decision.options.find((o) => o.id === optionId)?.label ?? optionId;
152→  });
153→
154→  protected isSelected(optionId: string): boolean {
155→    return this.selectedOptions().includes(optionId);
156→  }
157→
158→  protected canSubmit(): boolean {
159→    if (this.questionType() === "free_text") {
160→      return this.freeText().trim().length > 0;
161→    }
162→    return this.selectedOptions().length > 0;
163→  }
164→
165→  protected toggleOption(option: DecisionOption): void {
166→    if (this.questionType() === "single_choice") {
167→      this.selectedOptions.set([option.id]);
168→    } else {
169→      const current = this.selectedOptions();
170→      if (current.includes(option.id)) {
171→        this.selectedOptions.set(current.filter((id) => id !== option.id));
172→      } else {
173→        this.selectedOptions.set([...current, option.id]);
174→      }
175→    }
176→  }
177→
178→  protected onTextInput(event: Event): void {
179→    const textarea = event.target as HTMLTextAreaElement;
180→    this.freeText.set(textarea.value);
181→  }
182→
183→  protected onSubmit(): void {
184→    this.submitted.emit({
185→      roleId: this.card().roleId,
186→      selectedOptions: this.selectedOptions(),
187→      freeText: this.freeText(),
188→    });
189→  }
190→}
