  1→/**
  2→ * Shared Playwright fixtures for TFC e2e tests.
  3→ *
  4→ * Provides API route mocking helpers so tests run without a live backend.
  5→ */
  6→import { test as base, type Page, type Route } from "@playwright/test";
  7→
  8→/** Shape returned by POST /waiting-room/join */
  9→export interface MockParticipant {
 10→  id: string;
 11→  display_name: string;
 12→  role: string;
 13→  joined_at: string;
 14→}
 15→
 16→export interface MockRole {
 17→  id: string;
 18→  label: string;
 19→  player_type: string;
 20→}
 21→
 22→export interface MockScenario {
 23→  id: number;
 24→  title: string;
 25→  description: string;
 26→  domain_id: number | null;
 27→  content: {
 28→    roles?: MockRole[];
 29→    game_mode?: string;
 30→    [key: string]: unknown;
 31→  } | null;
 32→  version: number;
 33→  created_at: string;
 34→  updated_at: string;
 35→}
 36→
 37→export interface MockJoinableResponse {
 38→  exercise: Record<string, unknown>;
 39→  participants: MockParticipant[];
 40→  roles: MockRole[];
 41→  max_players: number;
 42→  requires_gm: boolean;
 43→}
 44→
 45→let participantCounter = 0;
 46→
 47→/** Build a mock participant object. */
 48→export function mockParticipant(
 49→  overrides: Partial<MockParticipant> = {},
 50→): MockParticipant {
 51→  participantCounter += 1;
 52→  return {
 53→    id: `p-${participantCounter}-${Date.now()}`,
 54→    display_name: overrides.display_name ?? "TestUser",
 55→    role: overrides.role ?? "player",
 56→    joined_at: new Date().toISOString(),
 57→    ...overrides,
 58→  };
 59→}
 60→
 61→/** Derive scenario roles from participant roles. */
 62→function deriveRoles(participants: MockParticipant[]): MockRole[] {
 63→  const seen = new Set<string>();
 64→  const roles: MockRole[] = [];
 65→  for (const p of participants) {
 66→    if (p.role === "game-master" || seen.has(p.role)) continue;
 67→    seen.add(p.role);
 68→    const isDecisionMaker = p.role === "decision_maker" || p.role === "co";
 69→    roles.push({
 70→      id: p.role,
 71→      label: p.role
 72→        .split(/[_-]/)
 73→        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
 74→        .join(" "),
 75→      player_type: isDecisionMaker ? "decision_maker" : "advisor",
 76→    });
 77→  }
 78→  return roles;
 79→}
 80→
 81→type Fixtures = {
 82→  /** Intercept all waiting-room API calls with configurable responses. */
 83→  mockApi: MockApi;
 84→};
 85→
 86→export class MockApi {
 87→  /** Accumulated participants per exercise_id (mirrors server state). */
 88→  readonly rooms = new Map<number, MockParticipant[]>();
 89→  /** Session code → exercise lookup payload. */
 90→  readonly codeMap = new Map<string, object>();
