 95→  /** Exercise ID → exercise payload (for GET /api/exercises/:id). */
 96→  readonly exerciseMap = new Map<number, object>();
 97→
 98→  readonly page: Page;
 99→  constructor(page: Page) {
100→    this.page = page;
