102→
103→  /** Register a session code so by-code lookup returns this exercise. */
104→  seedCode(code: string, exerciseId: number, gameMode = "classic"): void {
105→    const exercise = {
106→      id: exerciseId,
107→      title: "Seeded Exercise",
108→      description: "",
