170→      if (route.request().method() !== "GET") {
171→        await route.fallback();
172→        return;
173→      }
174→      await route.fulfill({
175→        status: 200,
176→        contentType: "application/json",
177→        body: JSON.stringify(this.scenarios),
178→      });
