200→
201→    // POST /api/exercises — create exercise
202→    await this.page.route("**/api/exercises", async (route) => {
203→      if (route.request().method() === "GET") {
204→        // GET /api/exercises/:id fallthrough handled below
205→        await route.fallback();
206→        return;
207→      }
208→      if (route.request().method() !== "POST") {
209→        await route.fallback();
210→        return;
211→      }
212→      const body = route.request().postDataJSON();
213→      const id = Math.floor(Math.random() * 9000) + 1000;
214→      const sessionCode = Math.random().toString(36).slice(2, 8).toUpperCase();
215→      await route.fulfill({
216→        status: 201,
217→        contentType: "application/json",
218→        body: JSON.stringify({
219→          id,
220→          title: body.title ?? "Test Exercise",
221→          description: body.description ?? "",
222→          phase: "setup",
223→          scenario_id: body.scenario_id ?? null,
224→          domain_id: null,
225→          time_factor: 1.0,
226→          game_mode: body.game_mode ?? "classic",
