233→
234→    // GET /api/exercises/:id — single exercise lookup
235→    await this.page.route("**/api/exercises/*", async (route) => {
236→      if (route.request().method() !== "GET") {
237→        await route.fallback();
238→        return;
239→      }
240→      const url = route.request().url();
241→      // Skip by-code, waiting-room, engine, joinable, and participants sub-paths
242→      if (/by-code|waiting-room|engine|participants|joinable/.test(url)) {
