244→        return;
245→      }
246→      const m = url.match(/exercises\/(\d+)$/);
247→      if (!m) {
248→        await route.fallback();
249→        return;
250→      }
251→      const id = Number(m[1]);
252→      const stored = this.exerciseMap.get(id);
253→      if (!stored) {
254→        await route.fulfill({ status: 404 });
255→        return;
256→      }
257→      await route.fulfill({
258→        status: 200,
259→        contentType: "application/json",
260→        body: JSON.stringify(stored),
261→      });
262→    });
263→
264→    // GET /api/exercises/by-code/:code — session code lookup
265→    await this.page.route("**/api/exercises/by-code/**", async (route) => {
266→      if (route.request().method() !== "GET") {
267→        await route.fallback();
