300→
301→    // GET /waiting-room
302→    await this.page.route("**/waiting-room", async (route) => {
303→      if (route.request().method() !== "GET") {
304→        await route.fallback();
305→        return;
306→      }
307→      const url = route.request().url();
308→      const exerciseId = this.extractExerciseId(url);
309→      await route.fulfill({
310→        status: 200,
311→        contentType: "application/json",
312→        body: JSON.stringify({
313→          exercise_id: exerciseId,
314→          participants: this.rooms.get(exerciseId) ?? [],
315→        }),
316→      });
