333→      }
334→      await route.fulfill({
335→        status: 200,
336→        contentType: "application/json",
337→        body: JSON.stringify(p),
338→      });
339→    });
340→
341→    // DELETE /participants/:id
342→    await this.page.route("**/waiting-room/participants/*", async (route) => {
343→      if (route.request().method() !== "DELETE") {
344→        await route.fallback();
345→        return;
346→      }
347→      const url = route.request().url();
348→      const exerciseId = this.extractExerciseId(url);
349→      const participantId = this.extractParticipantId(url);
350→      const removed = this.removeParticipant(exerciseId, participantId);
351→      await route.fulfill({ status: removed ? 204 : 404 });
352→    });
353→
354→    // Swallow WebSocket upgrade attempts (no real server)
355→    await this.page.route("**/ws?*", (route) =>
356→      route.abort("connectionrefused"),
357→    );
358→    await this.page.route("**/ws", (route) => route.abort("connectionrefused"));
359→  }
360→
361→  /**
362→   * Seed the room with participants before navigating.
363→   * Also auto-registers exercise + scenario data (with roles derived from
364→   * participants) unless the exercise was already explicitly seeded.
365→   */
366→  seed(
367→    exerciseId: number,
368→    participants: MockParticipant[],
369→    gameMode = "classic",
370→  ): void {
371→    this.rooms.set(exerciseId, [...participants]);
372→    if (!this.exerciseMap.has(exerciseId)) {
373→      const roles = deriveRoles(participants);
374→      const scenarioId = exerciseId;
375→      this.seedExercise(exerciseId, gameMode, scenarioId);
376→      if (!this.scenarios.find((s) => s.id === scenarioId)) {
377→        this.seedScenario({
378→          id: scenarioId,
379→          title: "Test Scenario",
380→          description: "",
381→          domain_id: null,
382→          content: { roles, game_mode: gameMode },
383→          version: 1,
384→          created_at: new Date().toISOString(),
385→          updated_at: new Date().toISOString(),
386→        });
387→      }
388→    }
389→  }
390→
391→  private addParticipant(exerciseId: number, p: MockParticipant): void {
392→    const list = this.rooms.get(exerciseId) ?? [];
393→    list.push(p);
394→    this.rooms.set(exerciseId, list);
395→  }
396→
397→  private updateRole(
398→    exerciseId: number,
399→    participantId: string,
400→    role: string,
401→  ): MockParticipant | null {
402→    const list = this.rooms.get(exerciseId) ?? [];
403→    const p = list.find((x) => x.id === participantId);
404→    if (!p) return null;
405→    p.role = role;
406→    return p;
407→  }
408→
409→  private removeParticipant(
410→    exerciseId: number,
411→    participantId: string,
412→  ): boolean {
413→    const list = this.rooms.get(exerciseId) ?? [];
414→    const idx = list.findIndex((x) => x.id === participantId);
415→    if (idx === -1) return false;
416→    list.splice(idx, 1);
417→    return true;
418→  }
419→
420→  private extractExerciseId(url: string): number {
421→    const m = url.match(/exercises\/(\d+)/);
422→    return m ? Number(m[1]) : 0;
423→  }
424→
425→  private extractParticipantId(url: string): string {
426→    const m = url.match(/participants\/([^/]+)/);
427→    return m ? m[1] : "";
428→  }
429→}
