200→  ngOnDestroy(): void {
201→    this.tick.stop();
202→    this.ws.disconnect();
203→    this.sub?.unsubscribe();
204→    this.connSub?.unsubscribe();
205→  }
206→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
207→    const decision = this.activeDecisions()[0];
208→    if (!decision) return;
209→    const role = this.store.context()?.roles?.find(
210→      (r) => r.id === submission.roleId,
211→    );
212→    if (role?.player_type === "decision_maker") {
213→      submitDecision(
214→        this.decisionApi,
215→        this.store,
216→        this.exerciseId(),
217→        decision,
218→        this.participantId(),
219→        submission,
220→      );
221→    } else {
222→      submitRoleRecommendation(
223→        this.decisionApi,
224→        this.exerciseId(),
225→        decision,
226→        this.participantId(),
227→        { roleId: submission.roleId, selectedOptions: submission.selectedOptions, freeText: submission.freeText },
228→      );
229→    }
230→    const updated = new Set(this.submittedRoles());
231→    updated.add(submission.roleId);
232→    this.submittedRoles.set(updated);
233→  }
234→}
