 1→// apps/tfc/frontend/src/app/features/player/role-card.types.ts
 2→import type { ActiveDecision } from "../../core/decision-api.service";
 3→import type { RoleDef } from "../../core/scenario-api.service";
 4→import type { EventSnapshot } from "../../core/generated/state-changes.types";
 5→
 6→/** Extract the roleId from a recommendation key ("participantId:roleId" or bare "roleId"). */
 7→export function extractRecRoleId(key: string): string {
 8→  const colonIdx = key.indexOf(":");
 9→  return colonIdx !== -1 ? key.slice(colonIdx + 1) : key;
10→}
11→
12→export interface AdvisorRec {
13→  roleId: string;
14→  roleLabel: string;
15→  selection: string | null; // option label, or null if pending
16→}
17→
18→export interface RoleCard {
19→  roleId: string;
20→  roleLabel: string;
21→  playerType: "decision_maker" | "advisor";
22→  intel: string | null;
23→  decision: ActiveDecision | null;
24→  status: "intel" | "active" | "done";
25→  advisorRecs: AdvisorRec[];
26→}
27→
28→export function buildRoleCards(
29→  roles: RoleDef[],
30→  event: EventSnapshot | null,
31→  decision: ActiveDecision | null,
32→  submittedRoles: Set<string>,
33→  showDecisionMaker: boolean,
34→): RoleCard[] {
35→  if (!event && !decision) return [];
36→  const roleDescs = event?.role_descriptions ?? {};
37→  const targetRoles = decision?.target_roles ?? [];
38→  const allRolesTargeted = targetRoles.length === 0 && decision != null;
39→
40→  return roles
41→    .filter((role) => {
42→      if (role.player_type === "decision_maker" && !showDecisionMaker)
43→        return false;
44→      const hasIntel = roleDescs[role.id] != null;
45→      const hasDecision = allRolesTargeted || targetRoles.includes(role.id);
46→      return hasIntel || hasDecision;
47→    })
48→    .map((role) => {
49→      const hasDecision = allRolesTargeted || targetRoles.includes(role.id);
50→      const isDone = hasDecision && submittedRoles.has(role.id);
51→      const advisorRecs: AdvisorRec[] = [];
52→
53→      if (role.player_type === "decision_maker" && decision) {
54→        const advisorTargets = targetRoles.filter((rid) => rid !== role.id);
55→        for (const advisorRoleId of advisorTargets) {
56→          const advisorRole = roles.find((r) => r.id === advisorRoleId);
57→          const recEntry = Object.entries(
58→            decision.recommendations || {},
59→          ).find(([key]) => extractRecRoleId(key) === advisorRoleId);
60→          const optionId = recEntry?.[1] ?? null;
61→          const optionLabel = optionId
62→            ? (decision.options.find((o) => o.id === optionId)?.label ?? optionId)
63→            : null;
64→          advisorRecs.push({
65→            roleId: advisorRoleId,
66→            roleLabel: advisorRole?.label ?? advisorRoleId,
67→            selection: optionLabel,
68→          });
69→        }
70→      }
71→
72→      const playerType =
73→        role.player_type === "decision_maker" || role.player_type === "advisor"
74→          ? role.player_type
75→          : "advisor"; // fallback — should never happen with valid scenario data
76→
77→      return {
78→        roleId: role.id,
79→        roleLabel: role.label,
80→        playerType,
81→        intel: roleDescs[role.id] ?? null,
82→        decision: hasDecision ? decision : null,
83→        status: hasDecision ? (isDone ? "done" : "active") : "intel",
84→        advisorRecs,
85→      } satisfies RoleCard;
86→    });
87→}
